101	    // ------------------------------------------------------------------
102	    router.put('/api/config/credentials', async (
103	        req: IncomingMessage,
104	        res: ServerResponse,
105	        _params: Record<string, string>,
106	    ): Promise<void> => {
107	        let body: unknown;
108	        try {
109	            body = await parseJsonBody(req);
110	        } catch (err) {
111	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
112	            return;
113	        }
114	
115	        if (!isPlainObject(body)) {
116	            sendError(res, 400, 'Request body must be a JSON object.');
117	            return;
118	        }
119	
120	        const { host, token } = body as { host?: unknown; token?: unknown };
121	
122	        if (typeof host !== 'string' || host.trim() === '') {
123	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
124	            return;
125	        }
126	
127	        if (typeof token !== 'string' || token.trim() === '') {
128	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
129	            return;
130	        }
131	
132	        const cleanHost = host.trim();
133	
134	        // Security: reject hosts with path separators or whitespace to prevent
135	        // key injection that could interfere with URL credential injection.
136	        if (/[\s/\\]/.test(cleanHost)) {
137	            sendError(res, 400, 'Field "host" must not contain path separators or whitespace.');
138	            return;
139	        }
140	
141	        // Defence-in-depth: reject prototype-pollution keys.
142	        if (['__proto__', 'constructor', 'prototype'].includes(cleanHost)) {
143	            sendError(res, 400, 'Field "host" contains a reserved name.');
144	            return;
145	        }
146	
147	        const cleanToken = token.trim();
148	
149	        // Update in-memory config.
150	        if (!appConfig.gitCredentials) {
151	            appConfig.gitCredentials = {};
152	        }
153	        appConfig.gitCredentials[cleanHost] = cleanToken;
154	
155	        // Persist to disk.
156	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
157	
158	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
159	    });
160	
161	    // ------------------------------------------------------------------
162	    // DELETE /api/config/credentials/:host — remove a single entry
163	    // Sync handler (no request body to parse — unlike the async PUT above).
164	    // ------------------------------------------------------------------
165	    router.delete('/api/config/credentials/:host', (
166	        _req: IncomingMessage,
167	        res: ServerResponse,
168	        params: Record<string, string>,
169	    ): void => {
170	        let host: string;
171	        try {
172	            host = decodeURIComponent(params['host']);
173	        } catch {
174	            sendError(res, 400, 'Malformed host parameter.');
175	            return;
176	        }
177	
178	        if (!appConfig.gitCredentials || !(host in appConfig.gitCredentials)) {
179	            sendError(res, 404, `No credential entry found for host "${host}".`);
180	            return;
181	        }
182	
183	        delete appConfig.gitCredentials[host];
184	
185	        // When the map is empty, remove the field entirely (undefined removes
186	        // it from config.json via saveConfigField).
187	        const isEmpty = Object.keys(appConfig.gitCredentials).length === 0;
188	        if (isEmpty) {
189	            appConfig.gitCredentials = undefined;
190	        }
191	
192	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
193	
194	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
195	    });
196	
197	    // ------------------------------------------------------------------
198	    // GET /api/config/polling — return the current polling interval
199	    // ------------------------------------------------------------------
200	    router.get('/api/config/polling', (
201	        _req: IncomingMessage,
202	        res: ServerResponse,
203	        _params: Record<string, string>,
204	    ): void => {
205	        sendJson(res, 200, {
206	            gitPollingIntervalSeconds: appConfig.gitPollingIntervalSeconds,
207	        });
208	    });
209	
210	    // ------------------------------------------------------------------
211	    // PUT /api/config/polling — update the polling interval
212	    // Validates: must be a finite integer >= 10.
213	    // ------------------------------------------------------------------
214	    router.put('/api/config/polling', async (
215	        req: IncomingMessage,
216	        res: ServerResponse,
217	        _params: Record<string, string>,
218	    ): Promise<void> => {
219	        let body: unknown;
220	        try {
221	            body = await parseJsonBody(req);
222	        } catch (err) {
223	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
224	            return;
225	        }
226	
227	        if (!isPlainObject(body)) {
228	            sendError(res, 400, 'Request body must be a JSON object.');
229	            return;
230	        }
231	
232	        const { seconds } = body as { seconds?: unknown };
233	
234	        if (typeof seconds !== 'number') {
