138	    /**
139	     * Restarts the background polling loop with a new interval.
140	     *
141	     * Stops the current loop (if running) and immediately starts a new one with
142	     * `intervalSeconds`.  This is the correct way to apply a live interval change
143	     * without creating a new `PollingManager` instance.
144	     *
145	     * @param intervalSeconds  The new polling interval in seconds.
146	     */
147	    restart(intervalSeconds: number): void {
148	        this.stop();
149	        this.start(intervalSeconds);
