161	     * Fetches live status for every repository in the specified workspace,
162	     * updates the in-memory cache with the results, and resolves when all
163	     * fetches have completed.
164	     *
165	     * Fetches are staggered by `STAGGER_MS` to avoid hammering the network.
166	     * Individual fetch failures are swallowed so that a single unreachable
167	     * repository does not prevent the others from being updated.  When an
168	     * `ErrorLogManager` is configured, failures are logged (with deduplication).
169	     *
170	     * @throws {Error} If the project or workspace does not exist (propagated
171	     *   from `WorkspaceManager`).
172	     */
173	    async refreshWorkspace(projectId: string, workspaceId: string): Promise<void> {
174	        const repoPaths = this.getRepoPaths(projectId, workspaceId);
175	        await this.fetchWithStagger(repoPaths);
