185	     *   `{projectsFolder}/{projectId}/{workspaceId}/{repoId}`
186	     */
187	    private getRepoPaths(projectId: string, workspaceId: string): string[] {
188	        const project = this.projectManager.getById(projectId);
189	        if (!project) {
190	            throw new Error(
191	                `PollingManager: project "${projectId}" does not exist.`,
192	            );
193	        }
194	        // Validate the workspace exists
195	        const ws = this.workspaceManager.getById(projectId, workspaceId);
196	        if (!ws) {
