209	     * every project that currently exists in the data store.
210	     */
211	    private getAllRepoPaths(): string[] {
212	        const repoPaths: string[] = [];
213	        for (const entry of this.projectManager.list()) {
214	            const project = this.projectManager.getById(entry.Id);
215	            if (!project) continue;
216	            for (const workspaceId of Object.keys(project.Workspaces)) {
217	                for (const repoId of project.Repositories) {
218	                    repoPaths.push(
